/bin/bash -lc "python3 - <<'PY'
import gzip, collections, sys
p='/workspace/inputs/identify.related.q1.tped.gz'
cnt=collections.Counter(); examples={}
with gzip.open(p,'rt') as f:
 for ln,line in enumerate(f):
  g=line.rstrip('\\n').split('\\t')
  a=set(g[4:])
  for x in a:
   cnt[x]+=1
  if '<DEL>' in a and '<DEL>' not in examples:
   examples['<DEL>']=(g[:6], list(a))
  if ln%100000==0: print(ln, file=sys.stderr)
print('distinct allele count',len(cnt),'total variant-alleles',sum(cnt.values()))
for a,c in cnt.most_common(30): print(repr(a),c)
print('examples',examples.get('<DEL>'))
PY"
